arguments.command:
cd /tmp/vally-eval-trial-6LByHr; mkdir -p tests/CheckoutPricing.UnitTests/Checkout
cat > src/CheckoutPricing.Application/CalculatePayableTotalHandler.cs <<'E'
namespace CheckoutPricing.Application;

public sealed record CalculatePayableTotal(string CustomerTier, decimal OrderSubtotal);

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotal command) => command.OrderSubtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Checkout/GoldCustomerDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class GoldCustomerDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        var total = new CalculatePayableTotalHandler().Handle(new CalculatePayableTotal("Gold", 100.00m));

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests --filter "FullyQualifiedName~GoldCustomerDiscountTests" --verbosity quiet 2>&1 | tail -20

